-- SOTA-SCAN-1 (2026-11-12, charter pillar autonomy; owner directive: the fleet acts as its own product manager and keeps adopting what the best players do).
-- Daily, the domain-managers workflow asks the Cloudflare agent to research one rotating topic (orchestration, eval loops, cost, memory, self-healing,
-- content pipelines) on the web, compare it with the fleet, and propose ONE single-file improvement. The reply goes through the existing ROADMAP-ORIGINATE-1
-- path (rm-parse, rm-file, rm-track, rm-deployed) as program QNFO.OPS, so each proposal becomes a ROADMAP-1 issue, a code task, a merged PR and a measured outcome.
-- Earlier proposals are fed back into the prompt so topics do not repeat. Stop: INSERT OR REPLACE INTO ops_config (key, value) VALUES ('sota_scan', 'off');
-- APPLY-BY: ci
-- DB: qnfo-audit
-- BACKUP: bak_20261112_sota_scan_workflow
-- Rollback: UPDATE fleet_tasks SET definition = (SELECT definition FROM bak_20261112_sota_scan_workflow WHERE id = 'domain-managers'), version = version + 1 WHERE id = 'domain-managers'; DROP VIEW IF EXISTS v_sota_scan;

CREATE TABLE IF NOT EXISTS bak_20261112_sota_scan_workflow AS SELECT id, definition, version FROM fleet_tasks WHERE id = 'domain-managers';

INSERT OR IGNORE INTO ops_config (key, value, note, updated_at) VALUES ('sota_scan', 'on', 'SOTA-SCAN-1 daily state-of-the-art scan; off stops it', datetime('now'));

DROP VIEW IF EXISTS v_sota_scan;
CREATE VIEW v_sota_scan AS
SELECT p.id, p.title, p.status, p.issue_id, p.task_id, p.pr_url, p.outcome, p.created_at, p.deployed_at
FROM roadmap_proposals p WHERE p.request_instance LIKE 'roadmap-QNFO.OPS-sota-%';

UPDATE fleet_tasks
SET definition = json_insert(definition, '$.steps[#]', json('{"type": "sql", "name": "sota-scan", "db": "AUDIT", "sql": "INSERT INTO cf_agent_requests (requester, kind, prompt, instance, priority) SELECT ''program-manager:QNFO.OPS'', ''run'', ''You are the product manager of the QNFO fleet (repository QNFO/qnfo-workers, Cloudflare Workers plus the D1 database qnfo-audit): an autonomous, self-improving fleet of agents that publishes research and runs its own administration. A product manager looks outward: find what the leading players and recent research are doing and bring the best of it into the product. Today''''s topic: '' || (CASE CAST(strftime(''%j'',''now'') AS INTEGER) % 6 WHEN 0 THEN ''agent orchestration and multi-agent coordination (planner/worker/reviewer patterns, durable execution, task routing)'' WHEN 1 THEN ''evaluation loops for agents (golden sets, LLM-judge calibration, regression gates, outcome-based metrics)'' WHEN 2 THEN ''cost reduction for LLM fleets (model routing and cascades, prompt and KV caching, batching, distillation to small models)'' WHEN 3 THEN ''agent memory (episodic and semantic memory, retrieval, consolidation, forgetting, provenance)'' WHEN 4 THEN ''self-healing and self-improving systems (automatic root cause analysis, canary and rollback, prompt and policy optimisation from outcomes)'' WHEN 5 THEN ''autonomous content pipelines (source-grounded generation, fact checking, quality scoring, distribution feedback)'' END) || ''. Search the web (vendor engineering blogs, arXiv, Cloudflare docs and changelog, major agent frameworks and their release notes) for practices from the last 12 months that are proven, not hype. Compare them with what the fleet already does (read the repository and qnfo-audit) and name the biggest gap. Cheap models must be used wherever they work and quality must never drop. Already proposed from earlier scans (do not repeat): '' || COALESCE((SELECT group_concat(substr(title, 1, 70), ''; '') FROM (SELECT title FROM roadmap_proposals WHERE request_instance LIKE ''roadmap-QNFO.OPS-sota-%'' ORDER BY id DESC LIMIT 10)), ''none'') || ''. Propose ONE improvement that a single-file change can deliver. Reply in exactly this form, each on its own line:'' || char(10) || ''TITLE: <under 80 characters, start with SOTA:>'' || char(10) || ''WHY: <the practice, who does it, the source URL, the gap here and the metric that will show it helped, under 90 words>'' || char(10) || ''code-task: repo=qnfo-workers path=<one worker.js, never qnfo-fleet-control, qnfo-ops, qnfo-deploy-guard, qnfo-code-orchestrator or .github>'' || char(10) || ''code-anchor: <verbatim text that occurs exactly once in that file, next to the edit>'' || char(10) || ''EDIT: <the exact change, under 120 words>'', ''roadmap-QNFO.OPS-sota-'' || strftime(''%Y%m%d'', ''now''), ''medium'' WHERE EXISTS (SELECT 1 FROM program_charters c WHERE c.program_code = ''QNFO.OPS'' AND c.status = ''active'') AND NOT EXISTS (SELECT 1 FROM cf_agent_requests r WHERE r.instance = ''roadmap-QNFO.OPS-sota-'' || strftime(''%Y%m%d'', ''now'') AND (r.status IN (''queued'', ''running'') OR (r.status = ''done'' AND COALESCE(r.result, '''') <> '''' AND COALESCE(r.result, '''') NOT LIKE ''(the model returned no text)%''))) AND COALESCE((SELECT value FROM ops_config WHERE key = ''persona_actions''), ''on'') <> ''off'' AND COALESCE((SELECT value FROM ops_config WHERE key = ''roadmap_originate''), ''on'') <> ''off'' AND COALESCE((SELECT value FROM ops_config WHERE key = ''sota_scan''), ''on'') <> ''off''"}')), version = version + 1
WHERE id = 'domain-managers' AND instr(definition, '"sota-scan"') = 0;
